import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.InputStream;
import java.io.OutputStream;
import android.net.Uri;
import android.content.Intent;
import androidx.core.content.FileProvider;

gameActivityClassAdditions.insert:
public boolean rdSaveImageToGallery(String path, String displayName) {
    try {
        java.io.File src = new java.io.File(path);
        if (!src.exists()) return false;
        android.content.ContentValues values = new android.content.ContentValues();
        values.put(android.provider.MediaStore.Images.Media.DISPLAY_NAME, displayName);
        values.put(android.provider.MediaStore.Images.Media.MIME_TYPE, "image/png");
        if (android.os.Build.VERSION.SDK_INT >= 29) {
            values.put(android.provider.MediaStore.Images.Media.RELATIVE_PATH, "Pictures/RandomDraw");
            values.put(android.provider.MediaStore.Images.Media.IS_PENDING, 1);
        }
        android.content.ContentResolver resolver = getContentResolver();
        android.net.Uri uri = resolver.insert(android.provider.MediaStore.Images.Media.EXTERNAL_CONTENT_URI, values);
        if (uri == null) return false;
        try (java.io.OutputStream out = resolver.openOutputStream(uri);
             java.io.InputStream in = new java.io.FileInputStream(src)) {
            byte[] buf = new byte[8192];
            int n;
            while ((n = in.read(buf)) > 0) out.write(buf, 0, n);
        }
        if (android.os.Build.VERSION.SDK_INT >= 29) {
            values.clear();
            values.put(android.provider.MediaStore.Images.Media.IS_PENDING, 0);
            resolver.update(uri, values, null, null);
        }
        return true;
    } catch (Exception e) {
        android.util.Log.e("RDShare", "rdSaveImageToGallery failed", e);
        return false;
    }
}


public boolean rdShareImage(String path) {
    try {
        File sourceFile = new File(path);
        if (!sourceFile.exists() || !sourceFile.isFile()) {
            android.util.Log.e("RDShare", "[RDShare] source image does not exist: " + path);
            return false;
        }

        File shareDirectory = new File(getCacheDir(), "share");
        if (!shareDirectory.exists()) {
            if (!shareDirectory.mkdirs()) {
                android.util.Log.e("RDShare", "[RDShare] could not create cache share directory");
                return false;
            }
        }
        File sharedFile = new File(shareDirectory, sourceFile.getName());
        if (!sourceFile.getCanonicalFile().equals(sharedFile.getCanonicalFile())) {
            try (InputStream input = new FileInputStream(sourceFile);
                 OutputStream output = new FileOutputStream(sharedFile)) {
                byte[] buffer = new byte[8192];
                int count;
                while ((count = input.read(buffer)) != -1) {
                    output.write(buffer, 0, count);
                }
            }
        }

        Uri imageUri = FileProvider.getUriForFile(
            this, getPackageName() + ".fileprovider", sharedFile);
        runOnUiThread(new Runnable() {
            @Override
            public void run() {
                try {
                    Intent sendIntent = new Intent(Intent.ACTION_SEND);
                    sendIntent.setType("image/png");
                    sendIntent.putExtra(Intent.EXTRA_STREAM, imageUri);
                    sendIntent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);

                    Intent chooser = Intent.createChooser(sendIntent, "Partager le dessin");
                    chooser.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);
                    startActivity(chooser);
                    android.util.Log.i("RDShare", "[RDShare] image share chooser started");
                } catch (Exception e) {
                    android.util.Log.e("RDShare", "[RDShare] failed to launch image share", e);
                }
            }
        });
        android.util.Log.i("RDShare", "[RDShare] image prepared for sharing");
        return true;
    } catch (Exception e) {
        android.util.Log.e("RDShare", "[RDShare] rdShareImage failed", e);
        return false;
    }
}
